/* Ispina Lokalnie — Kamera most w Ispinie (ZDW Kraków) */
(function(){
  'use strict';
  try{
    var d=document,panel=d.getElementById('iaP'),nav=d.getElementById('nav');if(!d.body||!panel||!nav||d.getElementById('vcamera'))return;
    var host=(location.hostname||'').toLowerCase();if(!window.IL_PWA_STANDALONE&&host!=='ispinalokalnie.com'&&host!=='www.ispinalokalnie.com'&&host!=='ispinalokalnie.wordpress.com')return;
    var BASE='https://www.zdw.krakow.pl/kamery/aster/120.jpg',INTERVAL=60000,timer=null,loading=false,lastOk=0,currentSrc='';
    var st=d.createElement('style');st.textContent='\
#vcamera .cam-head{padding:16px;margin-bottom:11px;border-radius:22px;color:#fff;background:linear-gradient(135deg,#205f78,#4d9fbd)}\
#vcamera .cam-card{padding:13px;background:#fff;border:1px solid #dfe8e2;border-radius:18px}.cam-frame{position:relative;overflow:hidden;border-radius:14px;background:#e9efec;min-height:210px;display:grid;place-items:center}.cam-frame img{display:block;width:100%;height:auto;object-fit:contain;cursor:zoom-in}.cam-load{position:absolute;inset:auto 10px 10px auto;background:#17362bcc;color:#fff;border-radius:99px;padding:6px 9px;font-size:11px}.cam-meta{margin-top:10px;font-size:12px;color:#526c61}.cam-status{margin-top:7px;padding:8px 9px;border-radius:10px;background:#f4f8f6;color:#526c61;font-size:12px}.cam-status.error{background:#fff0ee;color:#963129}.cam-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}.cam-btn{border:0;border-radius:12px;padding:10px 13px;background:#176f72;color:#fff;font-weight:850}.cam-btn.secondary{background:#e7f0ed;color:#244b40}.cam-note{font-size:11px;line-height:1.4;color:#687d74;margin-top:9px}.cam-overlay{position:fixed;z-index:100500;inset:0;background:#07120feF;display:none;align-items:center;justify-content:center;padding:18px}.cam-overlay.on{display:flex}.cam-overlay img{max-width:100%;max-height:90vh;object-fit:contain}.cam-close{position:absolute;top:max(12px,env(safe-area-inset-top));right:12px;border:0;border-radius:99px;width:44px;height:44px;background:#fff;color:#17362b;font-size:24px;font-weight:900}';d.documentElement.appendChild(st);
    var view=d.createElement('div');view.className='view';view.id='vcamera';view.innerHTML='<div class="cam-head"><div class="h">Kamera — most w Ispinie</div><div class="p" style="color:#eaf8ff;margin-top:4px">DW775 • Most w Ispinie</div></div><div class="cam-card"><div class="cam-frame"><img id="camImg" alt="Kamera drogowa ZDW — most w Ispinie"><div class="cam-load" id="camLoad">Ładowanie…</div></div><div class="cam-meta" id="camTime">Ostatnia aktualizacja: —</div><div class="cam-status" id="camStatus">Pobieram aktualny obraz…</div><div class="cam-actions"><button class="cam-btn" id="camRefresh">Odśwież</button><button class="cam-btn secondary" id="camRetry" hidden>Spróbuj ponownie</button></div><div class="cam-note">Źródło: Zarząd Dróg Wojewódzkich w Krakowie. Obraz jest zdjęciem JPG aktualizowanym cyklicznie, a nie transmisją wideo. Automatyczne odświeżanie działa tylko podczas oglądania tej sekcji.</div></div>';
    panel.appendChild(view);
    var settings=d.querySelector('#nav .nb[data-u=":set"]'),btn=d.createElement('button');btn.className='nb place';btn.setAttribute('data-u',':camera');btn.innerHTML='<span class="ni">📷</span>Kamera w Ispinie';var group=Array.prototype.find.call(nav.querySelectorAll('.ng'),function(n){return n.textContent.trim()==='O ISPINIE'}),next=group&&group.nextElementSibling;while(next&&!next.classList.contains('ng'))next=next.nextElementSibling;if(group)nav.insertBefore(btn,next);else nav.appendChild(btn);
    var overlay=d.createElement('div');overlay.className='cam-overlay';overlay.id='camOverlay';overlay.innerHTML='<button class="cam-close" id="camClose" aria-label="Zamknij">×</button><img id="camBig" alt="Kamera — most w Ispinie">';d.body.appendChild(overlay);
    function fmt(ts){var x=new Date(ts);return String(x.getHours()).padStart(2,'0')+':'+String(x.getMinutes()).padStart(2,'0')+':'+String(x.getSeconds()).padStart(2,'0')}
    function visible(){return view.classList.contains('on')&&panel.classList.contains('on')&&!d.hidden}
    function setStatus(txt,err){var x=d.getElementById('camStatus');if(!x)return;x.textContent=txt;x.className='cam-status'+(err?' error':'')}
    function refresh(force){if(loading||(!force&&!visible()))return;loading=true;var load=d.getElementById('camLoad'),retry=d.getElementById('camRetry');if(load)load.style.display='block';if(retry)retry.hidden=true;setStatus(lastOk?'Sprawdzam nowszy obraz…':'Pobieram aktualny obraz…',false);var pre=new Image();var url=BASE+(BASE.indexOf('?')>=0?'&':'?')+'_ilcb='+Date.now();pre.onload=function(){loading=false;currentSrc=url;lastOk=Date.now();var im=d.getElementById('camImg');if(im)im.src=url;var big=d.getElementById('camBig');if(big)big.src=url;var tm=d.getElementById('camTime');if(tm)tm.textContent='Ostatnia aktualizacja: '+fmt(lastOk);if(load)load.style.display='none';setStatus('Aktualny obraz z kamery ZDW.',false)};pre.onerror=function(){loading=false;if(load)load.style.display='none';if(retry)retry.hidden=false;setStatus('Nie udało się pobrać aktualnego obrazu z kamery.',true)};pre.src=url}
    function start(){stop();if(!visible())return;refresh(false);timer=setInterval(function(){refresh(false)},INTERVAL)}
    function stop(){if(timer){clearInterval(timer);timer=null}}
    function open(){try{history.pushState({ia:1,camera:1},'',location.href)}catch(e){}var drawer=d.getElementById('iaD'),shade=d.getElementById('sh');if(drawer)drawer.classList.remove('on');if(shade)shade.classList.remove('on');panel.querySelectorAll('.view').forEach(function(x){x.classList.remove('on')});view.classList.add('on');panel.classList.add('on');var sec=d.getElementById('sec');if(sec)sec.textContent='Kamera — most w Ispinie';panel.scrollTop=0;start()}
    btn.addEventListener('click',open);d.getElementById('camRefresh').addEventListener('click',function(){refresh(true)});d.getElementById('camRetry').addEventListener('click',function(){refresh(true)});d.getElementById('camImg').addEventListener('click',function(){if(!currentSrc)return;overlay.classList.add('on')});d.getElementById('camClose').addEventListener('click',function(){overlay.classList.remove('on')});overlay.addEventListener('click',function(e){if(e.target===overlay)overlay.classList.remove('on')});
    var mo=new MutationObserver(function(){if(visible())start();else stop()});mo.observe(view,{attributes:true,attributeFilter:['class']});mo.observe(panel,{attributes:true,attributeFilter:['class']});d.addEventListener('visibilitychange',function(){if(visible())start();else stop()});
  }catch(e){try{console.error('IL camera module:',e)}catch(_){}}
})();

